"""reports/monitoring.md (generated by `cmapss monitor`; do not edit)."""

from __future__ import annotations

from pathlib import Path

import pandas as pd

from cmapss_pm.config import Config
from cmapss_pm.monitoring.run import MonitorResult


def _md(df: pd.DataFrame, floatfmt: str = ".3f") -> str:
    return str(df.astype(object).to_markdown(index=False, floatfmt=floatfmt)) if len(df) else "_none_"


def write_monitoring_report(res: MonitorResult, cfg: Config) -> Path:
    mc = cfg.section("monitoring")
    tables = cfg.path("tables_dir")
    tables.mkdir(parents=True, exist_ok=True)
    for name, df in [
        ("monitoring_windows", res.windows),
        ("monitoring_performance", res.performance),
        ("monitoring_overall", res.overall),
        ("monitoring_top_drift", res.top_drift),
    ]:
        df.to_csv(tables / f"{name}.csv", index=False)
    s = res.signals
    worst = res.performance[res.performance.judged].sort_values("rmse_ratio", ascending=False).head(8)
    if res.retrain is None:
        retrain_text = "Retraining was not run" + (
            " (triggered, but `--retrain` was not given)." if s["retrain_triggered"] else " (not triggered)."
        )
    else:
        r = res.retrain
        retrain_text = (
            f"Retraining ran ({r['reason']}): challenger version {r['challenger_version']} has {r['primary_metric']} = "
            f"{r['challenger_value']:.3f} against the champion's {r['champion_value']}; champion alias "
            f"{'moved to the challenger' if r['promoted'] else 'kept on version ' + str(r['champion_version_before'])}."
        )
    tol, drop = 1 + float(mc["performance_tolerance"]), mc["coverage_drop"]
    perf_rule = (
        f"performance, {s['performance_scope']} (band RMSE > baseline x {tol:.2f}, or coverage < nominal - {drop})"
    )
    drift_rule = f"drift (>= {float(mc['drift_feature_share_alert']):.0%} of features with PSI > {mc['psi_alert']})"
    text = f"""<!-- GENERATED by `cmapss monitor` - do not edit by hand. -->
# Monitoring

Champion model version {res.model_version}; {res.meta["rows"]:,} logged replay predictions joined with their labels.
**SYNTHETIC REPLAY**: the monitored engines are the NASA test engines re-delivered batch by batch; their labels
are known in advance (a live fleet would learn them only after failure). Design: D-028, D-029.

## Decision

| signal | fired | retrains? |
|---|---|---|
| {perf_rule} | {s["performance"]} | {"yes" if "performance" in s["retrain_on"] else "no"} |
| {drift_rule} | {s["drift"]} | {"yes" if "drift" in s["retrain_on"] else "no (warning)"} |

**Retraining triggered: {s["retrain_triggered"]}.** {retrain_text}

## Windows (replay batches)

Each window is one replay batch: every engine's next {cfg.section("replay")["cycles_per_batch"]} cycles. PSI is
measured against the training deciles; `max_feature_psi` and the alert share exclude `cycle`, whose shift is the
replay's design (window 1 holds only cycles 1-25). Windows with fewer than {mc["min_rows"]} rows are listed but not
judged.

{_md(res.windows)}

Most-shifted features per window:

{_md(res.top_drift)}

## Performance against the out-of-fold baseline, by true-RUL band

Whole replay:

{_md(res.overall)}

Largest RMSE ratios among judged window-band cells ({s["windows_with_degraded_band_cells"]} windows have at least one
cell beyond tolerance; diagnostic only when the scope is `period`):

{_md(worst)}

## Reading the signals

Inputs drift as the replayed fleet ages: early windows hold only young, healthy engines, late windows only the few
long-lived engines close to failure. That shift is real but is not the model being wrong, which is why drift alone
only warns. Performance is compared within true-RUL bands so that a change in the mix of healthy and degraded engines
does not read as degradation.

Within a band, the replay still confounds age: all engines started together, so each window holds one age group.
The >125 band of windows 4-9 contains only engines that are already old yet far from failure (the long-lived ones),
which the model, using age, predicts conservatively. Their errors exceed the baseline by up to 75% in those windows,
while the same band over the whole replay is within tolerance. A real fleet mixes ages in every time slice; here the
retraining signal is therefore judged over the whole period (`monitoring.performance_scope`), and the per-window
cells are kept as diagnostics. An earlier run with per-window judgement fired, retrained a challenger (version 2,
same CV metric) and correctly did not promote it.
"""
    path = cfg.path("reports_dir") / "monitoring.md"
    path.write_text(text, encoding="utf-8")
    return path
